#include "BatchInitialTask.hpp"
#include <iostream>
using namespace udm;
template<class F>static bool until(F f){const auto end=GetTickCount64()+6000;while(!f()&&GetTickCount64()<end)Sleep(1);return f();}
int wmain(int argc,wchar_t** argv){
 if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;const auto check=[&](bool value,const char* name){checks.push_back({{"name",name},{"passed",value}});if(!value)throw std::runtime_error(name);};
 try{
  Manager manager(root/L"catalog");auto settings=manager.state["Settings"];settings["DownloadFolder"]=utf8((root/L"files").wstring());settings["CategoryFolders"]=false;manager.setSettings(settings);const auto before=manager.snapshot();const auto disk=readText(manager.root/L"state.json");std::vector<std::string> urls{"http://127.0.0.1:1/one.bin","http://127.0.0.1:1/two.MP4","http://127.0.0.1:1/one.bin"};std::vector<BrowserBatchRow> browser;for(auto& url:urls){BrowserBatchRow row;row.address=url;row.observedSize=4096;row.observedType="application/octet-stream";browser.push_back(std::move(row));}
  const auto original=browser[0].address;auto projected=projectBatchRows(urls,&browser,{},settings);check(projected.rows.size()==3&&projected.visible==std::vector<int>{0,1}&&projected.hasRepeated,"Initial browser projection retains source order and filters repeated plain links");check(!projected.rows[0].checked&&projected.rows[0].selectionTouched,"Projected browser rows retain explicit unchecked semantics");check(projected.rows[0].browserName=="one.bin"&&projected.rows[1].browserExtension==".mp4","URL names and normalized extensions are prepared before the GUI consumes rows");check(projected.rows[0].metadata["Size"]==4096&&projected.requests[0].address.empty(),"Scoped observed size metadata avoids an unnecessary preview request");check(fs::path(wide(projected.rows[0].projectedDestination)).lexically_normal()==(root/L"files"/L"one.bin").lexically_normal(),"The initial category destination is projected from the same settings snapshot");
  projected.rows[0].address="http://127.0.0.1:1/new.bin";check(batchRowFallback(projected.rows[0])=="new.bin"&&projected.rows[0].projectedDestination.empty(),"A later URL edit invalidates cached naming and destination evidence");check(browser[0].address==original&&urls[0]==original,"Projecting and editing a result never mutates immutable caller inputs");
  auto imports=projectBatchRows(urls,nullptr,{},settings);check(imports.visible.size()==3&&!imports.hasRepeated&&imports.rows[0].checked&&!imports.rows[0].selectionTouched,"Ordinary imports keep repeated rows and untouched default checks");check(imports.requests[0].address==urls[0]&&imports.rows[0].fallbackName=="one.bin","Import request and name preparation preserves each original address");
  auto hidden=browser;hidden[1].imageOnPage=true;check(projectBatchRows(urls,&hidden,{},settings).visible==std::vector<int>{0},"The initial browser image filter applies only to matched source context");hidden[1].address="http://other.example.test/unmatched";hidden[1].headers={{"Authorization","Bearer wrong-source"}};auto mismatched=projectBatchRows(urls,&hidden,{},settings);check(mismatched.visible==std::vector<int>({0,1})&&mismatched.requests[1].headers.empty()&&mismatched.requests[1].session.empty(),"Mismatched browser context supplies no observed hints, headers, image flag or website session");
  auto media=browser;media[0].media={{"action","adaptive"}};media[2].media={{"action","adaptive"}};media[0].suggestedName=media[2].suggestedName="selected.mp4";auto streams=projectBatchRows(urls,&media,{},settings);check(streams.visible.size()==3&&!streams.hasRepeated&&num(streams.rows[0].metadata,"Size")==-1&&streams.requests[0].address.empty(),"Media rows retain their names and unknown track-size state and are not deduplicated as ordinary URLs");
  auto authenticated=browser;authenticated[0].proxy={{"url",urls[0]},{"type","direct"}};authenticated[0].session={{"fixture","session"}};authenticated[0].headers={{"Cookie","owned-cookie"},{"User-Agent","Owned agent"}};Headers headers{{"Authorization","Basic owned-fixture"}};auto requests=projectBatchRows(urls,&authenticated,headers,settings);check(requests.requests[0].headers.at("Authorization")==headers.at("Authorization")&&requests.requests[0].headers.at("Cookie")=="owned-cookie"&&requests.requests[0].proxy==authenticated[0].proxy&&requests.requests[0].session==authenticated[0].session,"Prepared preview requests own the complete matching headers, route and session");
  settings["SiteLogins"]=Json::array({Json{{"Origin","http://127.0.0.1:1"}}});check(!projectBatchRows(urls,&browser,{},settings).requests[0].address.empty(),"A saved login prevents reusing observed metadata for a potentially different authenticated request");settings["SiteLogins"]=Json::array();settings["UseBrowserProxy"]=false;check(!projectBatchRows(urls,&authenticated,{},settings).requests[0].address.empty(),"Changing browser proxy policy invalidates the observed hint fast path");
  bool cancelled=false;int visited=0;try{projectBatchRows(urls,&browser,{},settings,[&]{if(++visited==2)throw Cancelled();});}catch(const Cancelled&){cancelled=true;}check(cancelled&&visited==2,"Projection cancellation is checked between rows without partially publishing the result");bool rejected=false;try{auto shortRows=browser;shortRows.pop_back();projectBatchRows(urls,&shortRows,{},settings);}catch(...){rejected=true;}check(rejected,"Projection rejects a browser-context cardinality mismatch");
  BatchInitialTask task;std::atomic_bool unlocked=false;task.start(manager,{},[&](const char* point){if(std::string(point)=="projecting-row"&&!unlocked){std::thread probe([&]{const auto end=GetTickCount64()+250;while(GetTickCount64()<end){std::unique_lock lock(manager.mutex,std::try_to_lock);if(lock.owns_lock()){unlocked=true;return;}Sleep(1);}});probe.join();if(!unlocked)throw std::runtime_error("Projection retained Manager");}},BatchInitialKind::Initial,&urls,&browser,{});check(until([&]{return task.ready();})&&task.take().error.empty()&&unlocked,"The owned initial worker projects rows only after releasing the catalog lock");check(manager.snapshot()==before&&readText(manager.root/L"state.json")==disk&&!manager.fileInfoDecisionPending,"Row preparation and metadata owner creation never mutate catalog state or accepted ownership");manager.stop();
 }catch(const std::exception& failure){error=failure.what();}
 atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;
}
